SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, COUNT(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_discount_pct, AVG(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_discount_pct, MAX(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_discount_pct, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_discount_pct, AVG(discount_pct) OVER (ORDER BY discount_pct, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS discount_pct_avg_6 FROM promotions;
